    Bug 1947720 - nsIMsgDatabase.getCachedHits() should return null for no cache (not throw). r=john.bieling

    Differential Revision: https://phabricator.services.mozilla.com/D238050

diff --git a/mail/components/extensions/ExtensionMessages.sys.mjs b/mail/components/extensions/ExtensionMessages.sys.mjs
index 1d70816107b..91c97911588 100644
--- a/mail/components/extensions/ExtensionMessages.sys.mjs
+++ b/mail/components/extensions/ExtensionMessages.sys.mjs
@@ -833,13 +833,13 @@ export function getMessagesInFolder(folder) {
       // Use cached hits or schedule the folder to be searched manually.
       // Note: The cached hits are stored in the db of each search folder using
       // the URI of the virtual folder as identifier.
-      try {
-        const cachedHits = searchFolder.msgDatabase.getCachedHits(folder.URI);
-        for (const msg of cachedHits) {
-          messages.push(msg);
-        }
-      } catch (e) {
+      const cachedHits = searchFolder.msgDatabase.getCachedHits(folder.URI);
+      if (!cachedHits) {
         searchFolders.push(searchFolder);
+        continue;
+      }
+      for (const msg of cachedHits) {
+        messages.push(msg);
       }
     }

